});

let found = [];
let step = 0;
rl.on('line', (line) => {
  if (line.includes('isCouponModalOpen') && line.includes('tool_calls')) {
    found.push({ step, line });
  }
  step++;
});

rl.on('close', () => {
  console.log('Found tool call occurrences with isCouponModalOpen:', found.length);
  found.forEach(f => {
    try {
      const parsed = JSON.parse(f.line);
      console.log('Step ' + f.step + ' type: ' + parsed.type + ' status: ' + parsed.status);
      parsed.tool_calls.forEach(tc => {
        console.log('  Tool name:', tc.name);
        if (tc.args && tc.args.TargetFile) {
          console.log('  TargetFile:', tc.args.TargetFile);
        }
      });
    } catch(e) {}
  });
});
